import { test, expect } from '@playwright/test';

// Copied from tests/e2e/helper/auth-helpers.ts to ensure standalone execution
async function authenticate(page) {
  await page.goto("/login");
  await page.fill('input[type="password"]', "vK8#zQ1p@Lr3wTx9!");
  await page.click('button:has-text("Login")');
  await page.waitForURL(/^(?!.*\/login)/, { timeout: 15000 });
}

/**
 * =============================================================================
 * BUG REPRO: Cutoff Time Force Close Not Respected
 * =============================================================================
 * 
 * This test reproduces the bug where positions are NOT force closed at cutoff time.
 * 
 * Expected Behavior:
 * - When cutoff time is set to 9:40, any open positions should be force closed at 9:40
 * - The force close should use the close price of the candle immediately before 9:40
 * 
 * Current Bug:
 * - Positions remain open past cutoff time instead of being force closed
 * 
 * This test will FAIL until the bug is fixed (Red state).
 */

test.describe('Bug Repro: Cutoff Time Force Close', () => {
  // Use the exact URL from the user's report
  const TARGET_URL = '/backtest/2025-07-09?strategy=strategy12.10.1&pt=38&sl=10&trg=8&candleType=1s&cutoffTime=09%3A40';

  test.beforeEach(async ({ page }) => {
    await authenticate(page);
  });

  test('should force close open positions at cutoff time (9:40)', async ({ page }) => {
    const consoleErrors: string[] = [];
    page.on("console", (msg) => {
      if (msg.type() === "error") {
        consoleErrors.push(msg.text());
      }
    });

    // Navigate to the page with cutoff time 9:40
    await page.goto(TARGET_URL);

    // Wait for page to load
    await page.waitForTimeout(3000);
    const chartContainer = page.getByTestId("chart-container");
    await expect(chartContainer).toBeVisible({ timeout: 10000 });

    // Extract trade data from the Algorithmic Trades table
    const tradeRows = page.locator('[data-testid="trade-row"]');
    const rowCount = await tradeRows.count();

    console.log(`Found ${rowCount} trade rows`);

    // Extract all trade data
    const tradeData = await tradeRows.evaluateAll(rows => rows.map(r => {
      const cells = r.querySelectorAll('td');
      return {
        id: cells[0]?.innerText?.trim() || '',
        time: cells[1]?.innerText?.trim() || '',
        type: cells[2]?.innerText?.trim() || '',
        price: cells[3]?.innerText?.trim() || '',
        note: cells[5]?.innerText?.trim() || '',
        net: cells[6]?.innerText?.trim() || ''
      };
    }));

    console.log("=== TRADE LOG START ===");
    tradeData.forEach((row, idx) => {
      console.log(`[${idx}] ${row.time} | ${row.type} | ${row.price} | ${row.note} | ${row.net}`);
    });
    console.log("=== TRADE LOG END ===");

    // Find all "Open" trades
    const openTrades = tradeData.filter(row => row.type.includes('Open'));
    console.log(`Found ${openTrades.length} open trades`);

    // Find all "Close" trades
    const closeTrades = tradeData.filter(row => row.type.includes('Close'));
    console.log(`Found ${closeTrades.length} close trades`);

    // CRITICAL ASSERTION: Every open trade must have a corresponding close
    // If a trade opens before 9:40, it MUST be closed at or before 9:40
    expect(openTrades.length, "Should have at least one open trade").toBeGreaterThan(0);
    expect(closeTrades.length, "Should have at least one close trade").toBeGreaterThan(0);

    // Check if any open trade is not closed by 9:40
    for (const openTrade of openTrades) {
      const openTimeMatch = openTrade.time.match(/(\d{2}:\d{2}:\d{2})/);
      if (!openTimeMatch) continue;

      const openTime = openTimeMatch[1];
      console.log(`Checking open trade at ${openTime}`);

      // If trade opens before 9:40, it must be closed by 9:40
      if (openTime < "09:40:00") {
        // Find the corresponding close trade
        const openId = openTrade.id;
        const closeTrade = tradeData.find(row => 
          row.type.includes('Close') && 
          row.id === openId.replace('open', 'close')
        );

        if (!closeTrade) {
          throw new Error(`Open trade ${openId} at ${openTime} has no corresponding close trade`);
        }

        const closeTimeMatch = closeTrade.time.match(/(\d{2}:\d{2}:\d{2})/);
        if (!closeTimeMatch) {
          throw new Error(`Could not parse close time for trade ${openId}`);
        }

        const closeTime = closeTimeMatch[1];
        console.log(`  Open: ${openTime}, Close: ${closeTime}, Note: ${closeTrade.note}`);

        // CRITICAL ASSERTION: Close time must be <= 9:40:00
        // If the trade is still open past 9:40, this test FAILS (Red state)
        expect(
          closeTime <= "09:40:00",
          `Trade opened at ${openTime} should be closed by 09:40:00, but close time is ${closeTime}. Note: ${closeTrade.note}`
        ).toBe(true);

        // If close time is exactly 9:40, verify it's a force close
        if (closeTime === "09:40:00" || closeTime.startsWith("09:40:")) {
          // The note should indicate a force close (or at least not be TP/SL if it's exactly at cutoff)
          console.log(`  Trade closed at cutoff time: ${closeTime}, Note: ${closeTrade.note}`);
          // Note: We can't assert exact note text yet since the feature doesn't exist
          // But we can verify it's closed by checking the time
        }
      }
    }

    // Verify zero console errors
    const realErrors = consoleErrors.filter(err => 
      !err.includes("Value is null") &&
      !err.includes("lightweight-charts") &&
      !err.includes("React DevTools") &&
      !err.includes("Download the React DevTools")
    );

    expect(
      realErrors,
      `Expected no console errors, but found ${realErrors.length} error(s): ${realErrors.join("; ")}`
    ).toHaveLength(0);
  });

  test('should emit no console errors', async ({ page }) => {
    const consoleErrors: string[] = [];
    page.on("console", (msg) => {
      if (msg.type() === "error") {
        consoleErrors.push(msg.text());
      }
    });

    await page.goto(TARGET_URL);
    await page.waitForTimeout(3000);

    const chartContainer = page.getByTestId("chart-container");
    await expect(chartContainer).toBeVisible({ timeout: 10000 });

    const realErrors = consoleErrors.filter(err => 
      !err.includes("Value is null") &&
      !err.includes("lightweight-charts") &&
      !err.includes("React DevTools") &&
      !err.includes("Download the React DevTools")
    );

    expect(
      realErrors,
      `Expected no console errors, but found ${realErrors.length} error(s): ${realErrors.join("; ")}`
    ).toHaveLength(0);
  });
});

