    }
  }
  return -1;
}

/**
 * Find the index of the first candle at or after the cutoff time.
 * 
 * This function finds the candle where we should force close any open positions.
 * Similar to find935CandleIndex, but uses the cutoffTime parameter instead of hardcoded 9:35.
 * 
 * @param candles - Array of candles to search
 * @param cutoffTime - Cutoff time in HH:MM format (e.g., "09:40")
 * @returns Index of first candle at or after cutoff time, or -1 if not found
 */
function findCutoffCandleIndex(candles: Candle[], cutoffTime: string): number {
  // Parse cutoff time (e.g., "09:40" -> hour=09, minute=40)
  const cutoffMatch = cutoffTime.match(/(\d{2}):(\d{2})/);
  if (!cutoffMatch) return -1;

  const [, cutoffHour, cutoffMinute] = cutoffMatch;
  const cutoffTimeStr = `${cutoffHour}:${cutoffMinute}:00`;

  // Find first candle at or after cutoff time
  for (let i = 0; i < candles.length; i++) {
    const candle = candles[i];
    const timeStr = candle.time;

    // Extract time from candle timestamp
    const timeMatch = timeStr.match(/(\d{2}):(\d{2}):(\d{2})/);
    if (!timeMatch) continue;

    const [, hour, minute] = timeMatch;
    const candleTimeStr = `${hour}:${minute}:00`;

    // Check if candle time is at or after cutoff time
    if (candleTimeStr >= cutoffTimeStr) {
      return i;
    }
  }
  return -1;
}

